import { type CnOptions, cn as mergeClasses } from "tailwind-variants";

export function cn(...classes: CnOptions): string {
  return mergeClasses(...classes) ?? "";
}

"use client";

import {
  Button as AriaButton,
  UNSTABLE_Toast as AriaToast,
  UNSTABLE_ToastContent as AriaToastContent,
  UNSTABLE_ToastRegion as AriaToastRegion,
  composeRenderProps,
  Text,
  type ToastOptions,
  UNSTABLE_ToastQueue as ToastQueue,
} from "react-aria-components";
import { flushSync } from "react-dom";
import { CheckCircle, InfoCircle, Warning, X } from "reicon-react";
import { tv } from "tailwind-variants";
import { cn } from "./utils";

const toastMotionStyles = `
@keyframes vip-toast-enter {
  from { opacity: 0; transform: translateY(12px); }
}
@keyframes vip-toast-exit {
  to { opacity: 0; transform: translateY(8px); }
}
@media (prefers-reduced-motion: no-preference) {
  ::view-transition-old(root), ::view-transition-new(root) { animation: none; }
  ::view-transition-group(.vip-toast) {
    animation-duration: 260ms;
    animation-timing-function: cubic-bezier(0.23, 1, 0.32, 1);
  }
  ::view-transition-new(.vip-toast):only-child {
    animation: vip-toast-enter 260ms cubic-bezier(0.23, 1, 0.32, 1) both;
  }
  ::view-transition-old(.vip-toast):only-child {
    animation: vip-toast-exit 180ms ease-in both;
  }
  @supports not (view-transition-name: none) {
    [data-slot="toast"] {
      animation: vip-toast-enter 260ms cubic-bezier(0.23, 1, 0.32, 1) both;
    }
  }
}
`;

const toastIconStyles = tv({
  base: "grid size-9 shrink-0 place-items-center rounded-lg",
  variants: {
    variant: {
      info: "bg-accent text-accent-foreground",
      success: "bg-success-subtle text-success-foreground",
      warning: "bg-warning-subtle text-warning-foreground",
    },
  },
  defaultVariants: { variant: "info" },
});

export interface ToastMessage {
  title: string;
  description?: string;
  variant?: "info" | "success" | "warning";
}

export const toastQueue = new ToastQueue<ToastMessage>({
  maxVisibleToasts: 3,
  wrapUpdate(fn) {
    if (
      typeof document !== "undefined" &&
      document.startViewTransition &&
      !window.matchMedia("(prefers-reduced-motion: reduce)").matches
    ) {
      document.startViewTransition(() => flushSync(fn));
    } else {
      fn();
    }
  },
});

export function showToast(message: ToastMessage, options?: ToastOptions) {
  const timeout =
    options?.timeout && options.timeout < 5000 ? 5000 : options?.timeout;
  return toastQueue.add(message, { ...options, timeout });
}

export function ToastViewport({
  className,
}: {
  className?: React.ComponentProps<typeof AriaToastRegion>["className"];
}) {
  return (
    <>
      <style>{toastMotionStyles}</style>
      <AriaToastRegion
        queue={toastQueue}
        data-slot="toast-viewport"
        aria-label="Notifications"
        className={composeRenderProps(className, (className) =>
          cn(
            "fixed inset-x-4 bottom-[calc(1rem+env(safe-area-inset-bottom))] z-50 flex flex-col-reverse gap-2 outline-none data-[focus-visible]:outline-2 data-[focus-visible]:outline-ring sm:inset-x-auto sm:end-4 sm:w-96",
            className,
          ),
        )}
      >
        {({ toast }) => {
          const variant = toast.content.variant ?? "info";
          const Icon =
            variant === "success"
              ? CheckCircle
              : variant === "warning"
                ? Warning
                : InfoCircle;
          return (
            <Toast toast={toast}>
              <Icon
                size={18}
                aria-hidden="true"
                className={toastIconStyles({ variant })}
              />
              <ToastContent>
                <ToastTitle>{toast.content.title}</ToastTitle>
                {toast.content.description && (
                  <ToastDescription>
                    {toast.content.description}
                  </ToastDescription>
                )}
              </ToastContent>
              <ToastClose />
            </Toast>
          );
        }}
      </AriaToastRegion>
    </>
  );
}

export function Toast({
  className,
  children,
  style,
  ...props
}: React.ComponentProps<typeof AriaToast>) {
  return (
    <AriaToast
      {...props}
      data-slot="toast"
      style={composeRenderProps(style, (style) => ({
        ...style,
        viewTransitionName: props.toast.key,
      }))}
      className={composeRenderProps(className, (className) =>
        cn(
          "flex items-start gap-3 rounded-xl bg-popover p-4 text-popover-foreground shadow-[var(--shadow-float)] ring-1 ring-border/70 outline-none data-[focus-visible]:outline-2 data-[focus-visible]:outline-ring [view-transition-class:vip-toast] forced-colors:border",
          className,
        ),
      )}
    >
      {(renderProps) =>
        typeof children === "function" ? children(renderProps) : children
      }
    </AriaToast>
  );
}

export function ToastContent({
  className,
  ...props
}: React.ComponentProps<typeof AriaToastContent>) {
  return (
    <AriaToastContent
      {...props}
      data-slot="toast-content"
      className={cn("min-w-0 flex-1", className)}
    />
  );
}

export function ToastTitle({
  className,
  ...props
}: React.ComponentProps<typeof Text>) {
  return (
    <Text
      {...props}
      slot="title"
      data-slot="toast-title"
      className={cn("block text-sm font-semibold", className)}
    />
  );
}

export function ToastDescription({
  className,
  ...props
}: React.ComponentProps<typeof Text>) {
  return (
    <Text
      {...props}
      slot="description"
      data-slot="toast-description"
      className={cn(
        "mt-1 block text-sm leading-5 text-muted-foreground",
        className,
      )}
    />
  );
}

export function ToastClose({
  className,
  children,
  ...props
}: React.ComponentProps<typeof AriaButton>) {
  return (
    <AriaButton
      {...props}
      slot="close"
      data-slot="toast-close"
      aria-label={props["aria-label"] ?? "Dismiss notification"}
      className={composeRenderProps(className, (className) =>
        cn(
          "-m-1 grid size-11 shrink-0 cursor-pointer place-items-center rounded-md text-muted-foreground outline-none transition-colors duration-150 hover:bg-muted hover:text-foreground data-[pressed]:bg-muted data-[focus-visible]:outline-2 data-[focus-visible]:outline-ring motion-reduce:transition-none",
          className,
        ),
      )}
    >
      {children ?? <X size={16} aria-hidden="true" />}
    </AriaButton>
  );
}

export { AriaToastRegion as ToastRegion };

import { tv, type VariantProps } from "tailwind-variants";

export const buttonStyles = tv({
  base: "inline-flex shrink-0 cursor-default items-center justify-center gap-2 whitespace-nowrap rounded-md font-medium tracking-[-0.01em] data-[disabled]:cursor-default data-[disabled]:opacity-50 data-[disabled]:shadow-none data-[focus-visible]:outline-2 data-[focus-visible]:outline-offset-3 data-[focus-visible]:outline-ring",
  variants: {
    variant: {
      default:
        "bg-primary text-primary-foreground shadow-[var(--shadow-card)] hover:bg-primary/90 data-[pressed]:bg-primary/90",
      secondary:
        "bg-secondary text-secondary-foreground hover:bg-border/70 data-[pressed]:bg-border/70",
      outline:
        "border border-border bg-card text-foreground shadow-[var(--shadow-card)] hover:bg-muted data-[pressed]:bg-muted",
      ghost: "text-foreground hover:bg-muted data-[pressed]:bg-muted",
      destructive:
        "bg-destructive text-background shadow-[var(--shadow-card)] hover:bg-destructive/90 data-[pressed]:bg-destructive/90",
      nav: "text-foreground hover:bg-muted aria-[pressed=true]:bg-accent aria-[pressed=true]:text-accent-foreground aria-[pressed=true]:hover:bg-accent",
    },
    size: {
      default: "h-11 px-5 text-sm",
      sm: "h-9 px-3.5 text-sm",
      lg: "h-12 px-6 text-sm",
      icon: "size-11 cursor-pointer p-0",
      nav: "h-9 w-full justify-center px-0 text-xs sm:justify-start sm:px-2.5",
    },
  },
  defaultVariants: { variant: "default", size: "default" },
});

export const buttonLinkStyles = tv({
  extend: buttonStyles,
  base: "cursor-pointer",
});

export type ButtonVariant = NonNullable<
  VariantProps<typeof buttonStyles>["variant"]
>;
export type ButtonSize = NonNullable<VariantProps<typeof buttonStyles>["size"]>;

"use client";

import { type MotionProps, motion, useReducedMotion } from "motion/react";
import {
  Button as AriaButton,
  type ButtonProps as AriaButtonProps,
  composeRenderProps,
} from "react-aria-components";
import {
  type ButtonSize,
  type ButtonVariant,
  buttonStyles,
} from "./button-styles";

export interface ButtonProps
  extends Omit<
    AriaButtonProps,
    | "style"
    | "onAnimationStart"
    | "onAnimationEnd"
    | "onAnimationIteration"
    | "onHoverStart"
    | "onHoverEnd"
  > {
  ref?: React.Ref<HTMLButtonElement>;
  variant?: ButtonVariant;
  size?: ButtonSize;
  static?: boolean;
  layout?: MotionProps["layout"];
}

const MotionButton = motion.create(AriaButton);

export function Button({
  className,
  variant = "default",
  size = "default",
  static: isStatic = false,
  layout,
  ...props
}: ButtonProps) {
  const reduceMotion = useReducedMotion();
  return (
    <MotionButton
      data-slot="button"
      data-variant={variant}
      data-size={size}
      layout={reduceMotion ? false : layout}
      whileTap={isStatic || reduceMotion ? undefined : { scale: 0.96 }}
      transition={{ duration: 0.14, ease: [0.23, 1, 0.32, 1] }}
      className={composeRenderProps(className, (className) =>
        buttonStyles({ variant, size, className }),
      )}
      {...props}
    />
  );
}

import type { HTMLAttributes } from "react";
import { tv, type VariantProps } from "tailwind-variants";
import { cn } from "./utils";

const badgeStyles = tv({
  base: "inline-flex min-h-7 items-center gap-1.5 rounded-full px-3 py-1 text-xs font-medium leading-4 tracking-normal shadow-[var(--shadow-card)] ring-1",
  variants: {
    variant: {
      neutral: "bg-secondary text-secondary-foreground ring-border",
      accent: "bg-accent text-accent-foreground ring-primary/15",
      success: "bg-success-subtle text-success-foreground ring-success/15",
      warning: "bg-warning-subtle text-warning-foreground ring-warning/20",
      error: "bg-card text-destructive ring-destructive/25",
      outline: "bg-transparent text-foreground ring-border",
    },
  },
  defaultVariants: { variant: "neutral" },
});

export interface BadgeProps extends HTMLAttributes<HTMLSpanElement> {
  variant?: NonNullable<VariantProps<typeof badgeStyles>["variant"]>;
  dot?: boolean;
}

export function Badge({
  variant = "neutral",
  dot = false,
  className,
  children,
  ...props
}: BadgeProps) {
  return (
    <span
      data-slot="badge"
      data-variant={variant}
      className={badgeStyles({ variant, className })}
      {...props}
    >
      {dot && <BadgeDot />}
      {children}
    </span>
  );
}

export function BadgeDot({
  className,
  ...props
}: HTMLAttributes<HTMLSpanElement>) {
  return (
    <span
      aria-hidden="true"
      {...props}
      data-slot="badge-dot"
      className={cn("size-1.5 rounded-full bg-current", className)}
    />
  );
}
